def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opps = 0
    total_alive_players = 1

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            total_alive_players += 1
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
                urgent_opps += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None and prev.get('status') != 'error':
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0, min(budget, 21.0))

    total_required = total_alive_players * WATER_REQ
    scarcity_ratio = float(supply) / float(total_required) if total_required > 0 else 1.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    my_urgent = hp <= 2 or no_water_days >= 2
    semi_urgent = hp <= 4 or no_water_days >= 1

    if my_urgent:
        target = max(63.0, highest_prev + 2.0)
    elif scarcity_ratio < 0.5:
        target = max(52.0, highest_prev + 1.5, avg_prev + 3.0)
    elif scarcity_ratio < 0.75:
        target = max(42.0, highest_prev + 1.0, avg_prev + 2.0)
    else:
        target = max(24.0, avg_prev * 0.9)

    if urgent_opps >= 2 and not my_urgent:
        target -= 4.0
    elif urgent_opps == 0 and scarcity_ratio < 0.75:
        target += 3.0

    if semi_urgent and not my_urgent:
        target += 6.0

    if hp >= 7 and scarcity_ratio >= 0.9:
        target = min(target, 28.0)

    if budget < 25:
        target = min(target, budget)
    elif budget < 50:
        target = min(target, budget * 0.9)
    else:
        target = min(target, budget * 0.75)

    if target < 0:
        target = 0.0

    return max(0, min(budget, float(target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, bid conservatively
    if not alive_opps:
        return min(my_status['budget'], int(DAILY_SALARY * 0.4))

    # Use yesterday trace if available (immediate reaction)
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Base bid depends on supply: higher supply -> lower urgency
    # Map supply in [MIN_SUPPLY, MAX_SUPPLY] to urgency in [0.8, 0.4]
    if MAX_SUPPLY - MIN_SUPPLY <= 0:
        urgency = 0.6
    else:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        urgency = 0.8 - 0.4 * t
        if urgency < 0.4:
            urgency = 0.4
        if urgency > 0.8:
            urgency = 0.8

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Urgency boosts
    if hp <= 2.0:
        urgency *= 1.25
    elif hp <= 3.0:
        urgency *= 1.10

    if no_water_days >= 2:
        urgency *= 1.25
    elif no_water_days == 1:
        urgency *= 1.10

    # If we saw strong opponent bids yesterday, match/beat slightly.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If they were near-salary, assume aggressive competition
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = highest_prev_bid + 1.0
        else:
            # Otherwise, bid enough to be competitive but not wasteful
            target = max(highest_prev_bid * 0.9, DAILY_SALARY * (0.45 + 0.35 * urgency))
    else:
        # No trace info: bid mid-high to secure water
        target = DAILY_SALARY * (0.45 + 0.35 * urgency)

    # Convert target to integer bid and cap by budget
    bid = int(target)
    if bid < 0:
        bid = 0
    if bid > budget:
        bid = int(budget)

    # Ensure we don't bid trivially low when hp/bad streak indicates need
    if (hp <= 3.0 or no_water_days >= 1) and bid < int(DAILY_SALARY * 0.55):
        bid = int(min(budget, DAILY_SALARY * 0.7))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = int(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)
    # Analyze yesterday's bid from first alive opponent
    prev_trace = alive_opponents[0].get('previous_trace', {})
    if prev_trace and 'bid' in prev_trace and prev_trace['bid'] is not None:
        opp_prev_bid = prev_trace['bid']
        # If opponent bid high yesterday, they might bid high again if still needy
        # Check opponent current HP
        opp_hp = alive_opponents[0]['hp']
        if opp_hp <= 2:
            # Opponent desperate, likely bid very high; outbid if we need it
            if hp <= 2:
                bid = min(budget, DAILY_SALARY * 0.95)
            else:
                bid = min(budget, max(DAILY_SALARY * 0.5, opp_prev_bid * 0.85))
        else:
            # Opponent not desperate, we can be more moderate
            if hp <= 2:
                bid = min(budget, DAILY_SALARY * 0.85)
            else:
                bid = min(budget, max(DAILY_SALARY * 0.4, opp_prev_bid * 0.7))
    else:
        # No trace, base on supply and hp
        if supply > (MAX_SUPPLY + MIN_SUPPLY) // 2:
            base = DAILY_SALARY * 0.35
        else:
            base = DAILY_SALARY * 0.5
        if hp <= 2:
            base = DAILY_SALARY * 0.85
        elif hp <= 4:
            base = max(base, DAILY_SALARY * 0.55)
        bid = min(budget, base)
    return max(0, bid)
